fn is_prime(n: i8) -> bool {
    // By definition, primes are >= 2.
    if n < 2 {
        return false;
    }

    // Now n is in [2, 127]. We'll test divisors k in [2, n).
    let n_i32 = n as i32;
    let mut k: i32 = 2;

    while k < n_i32 {
        if n_i32 % k == 0 {
            return false;
        }
        k += 1; // termination measure (n - k) strictly decreases
    }

    true
}